suppressPackageStartupMessages(library(tidyverse))
src <- './output/research_extensions/28_paper_state_guarded_refresh'
out <- dirname(normalizePath(sub('^--file=', '', grep('^--file=', commandArgs(FALSE), value=TRUE)[1])))
a <- read_csv(file.path(src,'all_att.csv'),show_col_types=FALSE)
th <- theme_bw(base_size=13)+theme(panel.grid.minor=element_blank(),panel.grid.major.y=element_blank(),strip.background=element_rect(fill='#f0f0f0',colour='#888888'),legend.position='bottom',legend.title=element_blank())
d <- a %>% filter(specification=='matched_pair_year', group %in% c('lower_income','higher_income'),analysis %in% c('main/log_rac_low','main/log_wac_low')) %>% mutate(side=if_else(str_detect(outcome,'rac'),'Resident-held jobs (log)','Workplace jobs (log)'),tier=factor(str_extract(outcome,'(low|mid|high)$'),levels=c('low','mid','high'),labels=c('Low wage','Middle wage','High wage')),income=factor(group,levels=c('lower_income','higher_income'),labels=c('Lower income','Higher income')))
stopifnot(nrow(d)==12)
p <- ggplot(d,aes(tier,estimate,colour=income))+geom_hline(yintercept=0,colour='grey55',linewidth=.4)+geom_errorbar(aes(ymin=estimate-1.96*std_error,ymax=estimate+1.96*std_error),width=.08,position=position_dodge(.25),linewidth=.45,alpha=.7)+geom_point(aes(shape=income),size=2.8,position=position_dodge(.25))+facet_wrap(~side,nrow=1)+scale_color_manual(values=c('#214F80','#B1672F'))+th+theme(panel.grid.major.x=element_blank(),panel.grid.major.y=element_line(colour='#eeeeee'),panel.spacing.x=grid::unit(.6,'cm'))+labs(y='Effect on log jobs',x=NULL)
ggsave(file.path(out,'income_wage.png'),p,width=10,height=4.3,dpi=200)
ggsave(file.path(out,'income_wage.pdf'),p,width=10,height=4.3)
write_csv(d,file.path(out,'income_wage_estimates.csv'))
def<-read_csv('./output/research_extensions/22_industry_rac_wac_20261022/industry_definitions.csv',show_col_types=FALSE)
d<-a%>%filter(str_starts(analysis,'industry/'),specification=='matched_pair_year',str_starts(outcome,'log_CNS'))%>%mutate(sector=sub('log_','',outcome),side=if_else(analysis=='industry/rac','RAC: jobs held by residents','WAC: jobs located in the tract'))%>%left_join(def,by='sector')%>%mutate(industry=factor(industry,levels=rev(def$industry)),estimate=100*estimate,std_error=100*std_error)
stopifnot(nrow(d)==40)
p<-ggplot(d,aes(estimate,industry))+geom_vline(xintercept=0,color='grey55')+geom_errorbar(aes(xmin=estimate-1.96*std_error,xmax=estimate+1.96*std_error),orientation='y',width=.12,color='#214F80')+geom_point(color='#214F80',size=1.7)+facet_wrap(~side)+th+labs(x='100 × effect on log jobs',y=NULL)
ggsave(file.path(out,'industry_log.png'),p,width=13,height=9,dpi=180)
ggsave(file.path(out,'industry_log.pdf'),p,width=13,height=9)
